/// Binary search helper: searches for the lower bound of `x` within the range [lo, hi)
/// in the sorted slice `a`. Returns an index `k`
/// such that all elements before `k` are < x and all from `k` onwards are >= x.
/// 
/// Precondition: lo <= hi <= a.len()
fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    let mut low = lo;
    let mut high = hi;
    while low < high {
        let mid = low + (high - low) / 2;
        if a[mid] < x {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    low
}

/// Searches for the insertion position `k` of `x` in the first 1000 elements
/// of the sorted slice `a`. Returns an index `k` with 0 <= k <= 1000 where:
///   - for all r < k, a[r] < x
///   - for all r >= k, a[r] >= x
///
/// Assumes `a.len() >= 1000` and elements `[0..1000]` are sorted nondecreasingly.
fn search_1000(a: &[i32], x: i32) -> usize {
    search_range_helper(a, x, 0, 1000)
}